contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function driving the test
    // no Ether is forwarded because C.sudicideAnyone is non-payable; include a dummy parameter to satisfy the input requirement
    function run(address /*unused*/ anyAddr) public payable {
        require(true);

        // observe before-values
        address beforeOwner = c.smartfix_owner(); if (__ESBMC_reverted()) return;
        uint256 beforeBalance = address(c).balance;

        // attempt the call and capture whether it reverted
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-values
        address afterOwner = c.smartfix_owner(); if (__ESBMC_reverted()) return;
        uint256 afterBalance = address(c).balance;

        // General invariant:
        // - If the call succeeded then this contract must have been the owner (msg.sender during the call is this contract),
        //   and C's balance cannot have increased (it should be <= beforeBalance).
        // - If the call reverted then owner and balance must be unchanged.
        assert(
            (!reverted && beforeOwner == address(this) && afterBalance <= beforeBalance)
            || (reverted && afterOwner == beforeOwner && afterBalance == beforeBalance)
        );
    }

    receive() external payable { }
}

