// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(address anyAddr) internal {
        vm.assume(true);
        address beforeOwner;
        try c.smartfix_owner() returns (address __r) { beforeOwner = __r; } catch { return; }
        uint256 beforeBalance = address(c).balance;
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        address afterOwner;
        try c.smartfix_owner() returns (address __r) { afterOwner = __r; } catch { return; }
        uint256 afterBalance = address(c).balance;
        assertTrue((!reverted && beforeOwner == address(this) && afterBalance <= beforeBalance)
            || (reverted && afterOwner == beforeOwner && afterBalance == beforeBalance));
    }

    function testFuzz_run(address anyAddr) public {
        vm.assume(anyAddr.code.length == 0 && uint160(anyAddr) > 0xffff && anyAddr != address(this) && anyAddr != address(c) && anyAddr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && anyAddr != 0x000000000000000000636F6e736F6c652e6c6f67 && anyAddr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && anyAddr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(anyAddr);
    }

    receive() external payable { }
}
